import{_ as r,a0 as a,w as c,s,ao as l,I as i,a1 as n,A as o,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse(`{"title":"在Linux中扩展/缩减LVM（第二部分） | LCTT x X-CMD","titleTemplate":false,"description":"在Linux中扩展/缩减LVM（第二部分） | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux中扩展/缩减LVM（第二部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux中扩展/缩减LVM（第二部分） | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II","title":"在Linux中扩展/缩减LVM（第二部分）","tag":"201410","desc":""},"relativePath":"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II.md","filePath":"[post].md"}`),d={name:"201410/20140813 How to Extend or Reduce LVM' s (Logical Volume Management) in Linux--Part II.md"};function m(g,e,u,w,L,V){const p=a("Link");return c(),s("div",null,[e[14]||(e[14]=l('<h1 id="在linux中扩展-缩减lvm-第二部分" tabindex="-1">在Linux中扩展/缩减LVM（第二部分） <a class="header-anchor" href="#在linux中扩展-缩减lvm-第二部分" aria-label="Permalink to “在Linux中扩展/缩减LVM（第二部分）”">​</a></h1><p>前面我们已经了解了怎样使用LVM创建弹性的磁盘存储。这里，我们将了解怎样来扩展卷组，扩展和缩减逻辑卷。在这里，我们可以缩减或者扩展逻辑卷管理（LVM）中的分区，LVM也可称之为弹性卷文件系统。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/LVM_extend.jpg" alt="Extend/Reduce LVMs in Linux"></p><h3 id="前置需求" tabindex="-1">前置需求 <a class="header-anchor" href="#前置需求" aria-label="Permalink to “前置需求”">​</a></h3>',4)),i("ul",null,[i("li",null,[n(p,{href:"http://linux.cn/article-3965-1.html"},{default:o(()=>[...e[0]||(e[0]=[t("使用LVM创建弹性磁盘存储——第一部分",-1)])]),_:1})])]),e[15]||(e[15]=l(`<h4 id="什么时候我们需要缩减卷" tabindex="-1">什么时候我们需要缩减卷？ <a class="header-anchor" href="#什么时候我们需要缩减卷" aria-label="Permalink to “什么时候我们需要缩减卷？”">​</a></h4><p>或许我们需要创建一个独立的分区用于其它用途，或者我们需要扩展任何空间低的分区。遇到这种情况时，使用 LVM我们可以很容易地缩减大尺寸的分区，以及扩展空间低的分区，只要按下面几个简易的步骤来即可。</p><h4 id="我的服务器设置-——-需求" tabindex="-1">我的服务器设置 —— 需求 <a class="header-anchor" href="#我的服务器设置-——-需求" aria-label="Permalink to “我的服务器设置 —— 需求”">​</a></h4><ul><li>操作系统 – 安装有LVM的CentOS 6.5</li><li>服务器IP – 192.168.0.200</li></ul><h3 id="如何扩展卷组以及缩减逻辑卷" tabindex="-1">如何扩展卷组以及缩减逻辑卷 <a class="header-anchor" href="#如何扩展卷组以及缩减逻辑卷" aria-label="Permalink to “如何扩展卷组以及缩减逻辑卷”">​</a></h3><h4 id="逻辑卷扩展" tabindex="-1">逻辑卷扩展 <a class="header-anchor" href="#逻辑卷扩展" aria-label="Permalink to “逻辑卷扩展”">​</a></h4><p>目前，我们已经有一个PV，VG和2个LV。让我们用下面的命令来列出它们。</p><pre><code># pvs
# vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Logical-Volume-Extending.jpg" alt="Logical Volume Extending"></p><p>逻辑卷扩展</p><p>在物理卷和卷组中没有空闲空间可用了，所以，现在我们不能扩展逻辑卷的大小。要扩展，我们需要添加一个物理卷（<strong>PV</strong>），然后通过扩展<strong>vg</strong>来扩展卷组，这样我们就会得到足够大的空间来扩展逻辑卷大小了。所以，首先我们应该去添加一个物理卷。</p><p>要添加一个新<strong>PV</strong>，我们必须使用fdisk来创建一个LVM分区。</p><pre><code># fdisk -cu /dev/sda
</code></pre><ul><li>选择<strong>n</strong>来创建新分区。</li><li>选择<strong>p</strong>来创建主分区。</li><li>选择我们需要创建的分区号。</li><li>如果有其它可用磁盘，请按<strong>1</strong>。</li><li>使用<strong>t</strong>来修改分区类型。</li><li>输入<strong>8e</strong>来将分区类型修改为Linux LVM。</li><li>使用<strong>p</strong>来打印创建的分区（这里我们没有使用该选项）。</li><li>按<strong>w</strong>写入修改。</li></ul><p>完成后重启系统。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-LVM-Partition.jpg" alt="Create LVM Partition"> 创建LVM分区</p><p>使用fdisk列出并检查我们创建的分区。</p><pre><code># fdisk -l /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-LVM-Partition.jpg" alt="Verify LVM Partition"> 验证LVM分区</p><p>接下来，使用下列命令来创建新<strong>PV</strong>（物理卷）。</p><pre><code># pvcreate /dev/sda1
</code></pre><p>使用下面的命令来验证pv。</p><pre><code># pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-Physical-Volume.jpg" alt="Create Physical Volume"></p><p>创建物理卷</p><h4 id="扩展卷组" tabindex="-1">扩展卷组 <a class="header-anchor" href="#扩展卷组" aria-label="Permalink to “扩展卷组”">​</a></h4><p>添加该pv到<strong>vg_tecmint</strong>卷组来扩展卷组的大小，以获取更多空间来扩展<strong>lv</strong>。</p><pre><code># vgextend vg_tecmint /dev/sda1
</code></pre><p>让我们检查现在正在使用的卷组的大小。</p><pre><code># vgs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Extend-Volume-Group.jpg" alt="Extend Volume Group"></p><p>扩展卷组</p><p>我们甚至可以看到哪个<strong>PV</strong>用于创建使用中的特定卷组。</p><pre><code># pvscan
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Volume-Group.jpg" alt="Check Volume Group"> 检查卷组</p><p>这里，我们可以看到卷组所处的物理卷。我们已经添加了一个pv，而且它完全空着。在扩展逻辑卷之前，让我们先看看我们所拥有的各个卷组的大小。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Each-Logical-Volume.jpg" alt="Check All Logical Volume"></p><p>检查所有逻辑卷</p><ul><li>LogVol00用于Swap。</li><li>LogVol01用于/。</li><li>现在我们有16.50GB大小的空间用于/（root）。</li><li>当前有4226物理扩展（PE）可用。</li></ul><p>现在，我们打算去扩展/分区<strong>LogVol01</strong>。在扩展后，我们可以像上面那样列出它的大小以确认。我们能可以使用GB或PE来扩展，这一点我已经在LVM第一部分解释过了，这里我使用PE来扩展。</p><p>要获取可用的物理扩展大小，运行以下命令。</p><pre><code># vgdisplay
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Available-Physical-Extend.jpg" alt="Check Available Physical Size"></p><p>检查可用的物理扩展</p><p>总共有<strong>4607</strong>空闲PE可用，亦即有<strong>18GB</strong>空间空间可用。因此，我们可以将我们的逻辑卷扩展到<strong>18GB</strong>这么大。让我们使用PE大小来扩展。</p><pre><code># lvextend -l +4607 /dev/vg_tecmint/LogVol01
</code></pre><p>使用<strong>+</strong>来添加更多空间。在扩展后，我们需要改变文件系统大小，使用以下命令。</p><pre><code># resize2fs /dev/vg_tecmint/LogVol01
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Expand-Logical-Volume.jpg" alt="Expand Logical Volume"> 扩展逻辑卷</p><ul><li>用来使用物理扩展扩展逻辑卷的命令。</li><li>这里我们可以看到它从16.51GB扩展到了34GB。</li><li>如果文件系统已被挂载并处于使用中，改变文件系统大小。</li><li>要扩展逻辑卷，我们不需要卸载文件系统</li></ul><p>现在，让我们看看当前使用的改变大小后的逻辑卷。</p><pre><code># lvdisplay
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Resize-Logical-Volume.jpg" alt="Resize Logical Volume"></p><p>改变逻辑卷大小</p><ul><li>LogVol01用于扩展的卷 /。</li><li>扩展后，从16.50GB上升到了34.50GB。</li><li>C当前扩展，在扩展前有4226，我们已经添加了4607个扩展，因此现在有8833。</li></ul><p>现在，如果我们检查可用的vg的话，空闲PE将会是0。</p><pre><code># vgdisplay
</code></pre><p>查看扩展的结果。</p><pre><code># pvs
# vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Resize-Partition.jpg" alt="Verify Resize Partition"></p><p>验证分区大小改变</p><ul><li>添加的新物理卷。</li><li>卷组vg_tecmint从17.51GB扩展到了35.50GB。</li><li>逻辑卷LogVol01从16.51GB扩展到了34.50GB。</li></ul><p>这里，我们已经完成扩展卷组和逻辑卷的过程。让我们一起迈向逻辑卷管理中一些有趣的部分。</p><h4 id="缩减逻辑卷-lvm" tabindex="-1">缩减逻辑卷（LVM） <a class="header-anchor" href="#缩减逻辑卷-lvm" aria-label="Permalink to “缩减逻辑卷（LVM）”">​</a></h4><p>这里，我们将了解如何缩减逻辑卷。人人都说它很危险，在缩减lvm的时候可能会导致灾难。缩减lvm在逻辑卷管理中比其它部分要来得确实有趣得多。</p><ul><li>在开始之前，备份好数据总是对的，这样如果出错，就不会头痛了。</li><li>要缩减逻辑卷，需要小心翼翼地完成5个步骤。</li><li>在扩展一个卷的时候，我们可以在该卷挂载时扩展它（在线），但对于缩减，我们必须在缩减前卸载文件系统。</li></ul><p>让我们来了解一下下面这5个步骤。</p><ul><li>卸载文件系统以便缩减。</li><li>在卸载后检查文件系统。</li><li>缩减文件系统。</li><li>5减少当前逻辑卷大小。</li><li>再检查文件系统以防出错。</li><li>将文件系统再次挂载回去。</li></ul><p>为了演示，我已经创建了独立的卷组和逻辑卷。这里，我将缩减逻辑卷<strong>tecmint_reduce_test</strong>。现在它有18GB大小，我们需要将它缩减到<strong>10GB</strong>而不丢失数据。也就是说，我们需要从<strong>18GB</strong>中减少<strong>8GB</strong>。卷中已经有<strong>4GB</strong>被使用。</p><pre><code>18GB ---&gt; 10GB
</code></pre><p>在缩减大小的时候，我们只需要缩减8GB，所以在缩减后它总计会有10GB。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Logical-Volume.jpg" alt="Reduce Logical Volume"> 缩减逻辑卷</p><p>这里，我们可以看到文件系统信息。</p><pre><code># df -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-File-System-Size.jpg" alt="Check File System Size"> 检查文件系统大小</p><ul><li>卷大小是18GB。</li><li>它已经使用了3.9GB。</li><li>可用空间是13GB。</li></ul><p>首先，卸载挂载点。</p><pre><code># umount -v /mnt/tecmint_reduce_test/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Unmount-Parition.jpg" alt="Unmount Parition"></p><p>卸载分区</p><p>然后，使用以下命令来检查文件系统错误。</p><pre><code># e2fsck -ff /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Scan-Parition-for-Errors.jpg" alt="Scan Parition for Errors"> 扫描分区错误</p><p><strong>注意</strong>：必须通过所有文件系统检查的5个步骤，若未完全通过，则你的文件系统可能存在问题。</p><p>接下来，缩减文件系统。</p><pre><code># resize2fs /dev/vg_tecmint_extra/tecmint_reduce_test 8GB
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-File-System.jpg" alt="Reduce File System"> 缩减文件系统</p><p>使用GB来缩减逻辑卷。</p><pre><code># lvreduce -L -8G /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Logical-Volume-Partition.jpg" alt="Reduce Logical Partition"> 缩减逻辑分区</p><p>要使用PE来缩减逻辑卷，我们需要知道默认PE大小和卷组的总PE大小，以进行一次小小的计算来得出准确的缩减大小。</p><pre><code># lvdisplay vg_tecmint_extra
</code></pre><p>这里，我们需要使用bc命令来做一些小计算来获得10GB的PE大小。</p><pre><code>1024MB x 10GB = 10240MB or 10GB

10240MB / 4PE = 2048PE
</code></pre><p>按<strong>CTRL+D</strong>来退出BC。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/bc-command.jpg" alt="Calculate PE Size"></p><p>计算PE大小</p><p>使用PE来缩减大小。</p><pre><code># lvreduce -l -2048 /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Reduce-Size-Using-PE.jpg" alt="Reduce Size Using PE"> 使用PE来缩减大小</p><p>将文件系统大小调整回去。在这一步中，如果发生任何错误，这就意味着我们已经将文件系统搞乱了。</p><pre><code># resize2fs /dev/vg_tecmint_extra/tecmint_reduce_test
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Resize-File-System.jpg" alt="Resize File System"></p><p>将文件系统挂载回同样的挂载点。</p><pre><code># mount /dev/vg_tecmint_extra/tecmint_reduce_test /mnt/tecmint_reduce_test/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Mount-File-System.jpg" alt="Mount File System"> 挂载文件系统</p><p>检查分区和文件的大小。</p><pre><code># lvdisplay vg_tecmint_extra
</code></pre><p>这里，我们可以看到最后的结果，逻辑已经被缩减到10GB。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-Logical-Volume-Size.jpg" alt="Verify Logical Volume Size"></p><p>在本文中，我们已经了解了如何来扩增卷组、逻辑卷以及缩减逻辑卷。在下一部分（第三部分）中，我们将了解如何为逻辑卷做快照并将它恢复到更早的状态。</p><hr>`,113)),i("p",null,[e[2]||(e[2]=t("via: ",-1)),n(p,{href:"http://www.tecmint.com/extend-and-reduce-lvms-in-linux/"},{default:o(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/extend-and-reduce-lvms-in-linux/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=t("作者：",-1)),n(p,{href:"http://www.tecmint.com/author/babinlonston/"},{default:o(()=>[...e[3]||(e[3]=[t("Babin Lonston",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：",-1)),n(p,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[4]||(e[4]=[t("GOLinux",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),n(p,{href:"https://github.com/wxy"},{default:o(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),n(p,{href:"http://linux.cn/"},{default:o(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const v=r(d,[["render",m]]);export{x as __pageData,v as default};
